import {PropertyInspector,type PropertyInspectorProps} from '@/components/nyc-tron/ui/components/forge/inputs/PropertyInspector';
export interface PageSetup {width:number;height:number;orientation:'portrait'|'landscape';marginTop:number;marginBottom:number;marginLeft:number;marginRight:number;columns:number;columnGap:number;section:'continuous'|'next-page'|'even-page'|'odd-page'}
export function validatePageSetup(v:PageSetup):void{
 if(![v.width,v.height,v.marginTop,v.marginBottom,v.marginLeft,v.marginRight,v.columns,v.columnGap].every(Number.isFinite)||v.width<36||v.height<36||v.width>14400||v.height>14400||[v.marginTop,v.marginBottom,v.marginLeft,v.marginRight,v.columnGap].some(n=>n<0)||v.marginTop+v.marginBottom>=v.height||v.marginLeft+v.marginRight+(v.columns-1)*v.columnGap>=v.width||!Number.isInteger(v.columns)||v.columns<1||v.columns>32||!['portrait','landscape'].includes(v.orientation)||!['continuous','next-page','even-page','odd-page'].includes(v.section))throw new RangeError('Page margins and columns must leave a positive text area');
}
export interface PageSetupPanelProps extends Omit<PropertyInspectorProps,'label'|'fields'|'onCommit'> {value:PageSetup;papers:readonly {id:string;label:string;width:number;height:number}[];onCommit:(value:PageSetup,signal?:AbortSignal)=>unknown}
export function PageSetupPanel({value,papers,onCommit,...props}:PageSetupPanelProps){validatePageSetup(value);if(papers.length>128||new Set(papers.map(p=>p.id)).size!==papers.length||papers.some(p=>!p.id.trim()||p.id==='custom'||!p.label.trim()||![p.width,p.height].every(n=>Number.isFinite(n)&&n>=36&&n<=14400)))throw new RangeError('Too many paper sizes');return <PropertyInspector {...props} label="Page setup" fields={[
 ...(['width','height','marginTop','marginBottom','marginLeft','marginRight','columnGap'] as const).map(id=>({kind:'number' as const,id,label:{width:'Paper width',height:'Paper height',marginTop:'Top margin',marginBottom:'Bottom margin',marginLeft:'Left margin',marginRight:'Right margin',columnGap:'Column gap'}[id],value:value[id],min:id==='width'||id==='height'?36:0,max:14400,step:.5,unit:'pt'})),
 {kind:'number',id:'columns',label:'Column count',value:value.columns,min:1,max:32,step:1},
 {kind:'choice',id:'orientation',label:'Paper orientation',value:value.orientation,choices:['portrait','landscape'].map(id=>({id,label:id}))},
 {kind:'choice',id:'paperPreset',label:'Paper size preset',value:papers.find(p=>(value.orientation==='portrait'?p.width:p.height)===value.width&&(value.orientation==='portrait'?p.height:p.width)===value.height)?.id??'custom',choices:[{id:'custom',label:'Custom paper',disabled:true},...papers.map(p=>({id:p.id,label:p.label}))]},
 {kind:'choice',id:'section',label:'Section start',value:value.section,choices:['continuous','next-page','even-page','odd-page'].map(id=>({id,label:id}))}
 ]} onCommit={(id,v,s)=>{const next={...value};if(id!=='paperPreset')Object.assign(next,{[id]:v});if(id==='orientation'&&v!==value.orientation){next.width=value.height;next.height=value.width;}if(id==='paperPreset'){const p=papers.find(p=>p.id===v);if(!p)throw new Error('Paper preset unavailable');next.width=value.orientation==='portrait'?p.width:p.height;next.height=value.orientation==='portrait'?p.height:p.width;}validatePageSetup(next);return onCommit(next,s);}}/>;}
